-- Jewellery Order Book — schema
--
-- Conventions:
--   money        INTEGER, paise (never a float)
--   weight       INTEGER, milligrams
--   carats       INTEGER, thousandths of a carat
--   percentages  INTEGER, basis points (800 = 8%)
--   identifiers  TEXT, UUIDv7 generated by the application
--   enums        TEXT with CHECK constraints, so the database is readable on its own
--
-- Applying this file to an empty database creates everything. It is idempotent:
-- every object is created with IF NOT EXISTS.

PRAGMA foreign_keys = ON;

-- ---------------------------------------------------------------- customer

CREATE TABLE IF NOT EXISTS customer (
    id            TEXT PRIMARY KEY,
    name          TEXT NOT NULL,
    phone         TEXT NOT NULL,
    address       TEXT NOT NULL,
    pan           TEXT,
    email         TEXT,
    gstin         TEXT,
    credit_days   INTEGER NOT NULL DEFAULT 0,
    notes         TEXT,
    is_active     INTEGER NOT NULL DEFAULT 1,
    created_at    TEXT NOT NULL,
    updated_at    TEXT NOT NULL,
    CHECK (length(trim(name)) > 0),
    CHECK (length(trim(phone)) > 0),
    CHECK (length(trim(address)) > 0),
    CHECK (pan IS NULL OR length(pan) = 10)
);

CREATE INDEX IF NOT EXISTS ix_customer_name  ON customer(name);
CREATE INDEX IF NOT EXISTS ix_customer_phone ON customer(phone);

-- ---------------------------------------------------------------- order

CREATE TABLE IF NOT EXISTS sales_order (
    id                     TEXT PRIMARY KEY,
    number                 INTEGER NOT NULL UNIQUE,
    customer_id            TEXT NOT NULL REFERENCES customer(id) ON DELETE RESTRICT,
    order_date             TEXT NOT NULL,
    expected_delivery_date TEXT,
    status                 TEXT NOT NULL DEFAULT 'Pending'
                             CHECK (status IN ('Pending','InProgress','Ready','Delivered','Cancelled')),
    notes                  TEXT,
    cancellation_reason    TEXT,
    created_at             TEXT NOT NULL,
    updated_at             TEXT NOT NULL
);

CREATE INDEX IF NOT EXISTS ix_order_customer ON sales_order(customer_id);
CREATE INDEX IF NOT EXISTS ix_order_date     ON sales_order(order_date);
CREATE INDEX IF NOT EXISTS ix_order_status   ON sales_order(status);

CREATE TABLE IF NOT EXISTS order_line (
    id                   TEXT PRIMARY KEY,
    order_id             TEXT NOT NULL REFERENCES sales_order(id) ON DELETE CASCADE,
    position             INTEGER NOT NULL,

    item_name            TEXT NOT NULL,
    item_description     TEXT,
    quantity             INTEGER NOT NULL DEFAULT 1 CHECK (quantity > 0),

    metal_type           TEXT NOT NULL CHECK (metal_type IN ('Gold','Silver','Platinum')),
    metal_purity         TEXT,
    gross_weight_mg      INTEGER NOT NULL CHECK (gross_weight_mg > 0),
    rate_per_gram_paise  INTEGER NOT NULL CHECK (rate_per_gram_paise >= 0),
    rate_date            TEXT NOT NULL,
    wastage_pct_bp       INTEGER NOT NULL DEFAULT 0 CHECK (wastage_pct_bp >= 0),

    making_type          TEXT NOT NULL DEFAULT 'PerGram'
                           CHECK (making_type IN ('PerGram','Percent','Fixed')),
    making_rate          INTEGER NOT NULL DEFAULT 0 CHECK (making_rate >= 0),

    other_charges_paise  INTEGER NOT NULL DEFAULT 0 CHECK (other_charges_paise >= 0),
    discount_paise       INTEGER NOT NULL DEFAULT 0 CHECK (discount_paise >= 0),

    -- The four optional tax components. NULL means the box was not ticked.
    tax_gold_bp          INTEGER CHECK (tax_gold_bp    IN (300,500,900,1200,1800,2800)),
    tax_wastage_bp       INTEGER CHECK (tax_wastage_bp IN (300,500,900,1200,1800,2800)),
    tax_making_bp        INTEGER CHECK (tax_making_bp  IN (300,500,900,1200,1800,2800)),
    tax_stone_bp         INTEGER CHECK (tax_stone_bp   IN (300,500,900,1200,1800,2800)),

    -- Derived by the pricing engine and stored, so the printed bill reconciles.
    net_weight_mg        INTEGER NOT NULL DEFAULT 0,
    wastage_weight_mg    INTEGER NOT NULL DEFAULT 0,
    metal_value_paise    INTEGER NOT NULL DEFAULT 0,
    wastage_charge_paise INTEGER NOT NULL DEFAULT 0,
    making_charges_paise INTEGER NOT NULL DEFAULT 0,
    stone_value_paise    INTEGER NOT NULL DEFAULT 0,
    subtotal_paise       INTEGER NOT NULL DEFAULT 0,
    taxable_paise        INTEGER NOT NULL DEFAULT 0,
    tax_paise            INTEGER NOT NULL DEFAULT 0,
    line_total_paise     INTEGER NOT NULL DEFAULT 0
);

CREATE INDEX IF NOT EXISTS ix_line_order ON order_line(order_id, position);

CREATE TABLE IF NOT EXISTS line_stone (
    id                TEXT PRIMARY KEY,
    order_line_id     TEXT NOT NULL REFERENCES order_line(id) ON DELETE CASCADE,
    position          INTEGER NOT NULL,

    category          TEXT NOT NULL CHECK (category IN ('Diamond','Precious','SemiPrecious')),
    name              TEXT,
    origin_type       TEXT,
    treatment         TEXT,
    shape             TEXT,
    stone_count       INTEGER NOT NULL DEFAULT 1 CHECK (stone_count > 0),
    total_carats_milli INTEGER NOT NULL DEFAULT 0 CHECK (total_carats_milli >= 0),

    colour_grade      TEXT,
    clarity_grade     TEXT,
    certification_lab TEXT,
    certificate_number TEXT,

    stone_value_paise INTEGER NOT NULL DEFAULT 0 CHECK (stone_value_paise >= 0),
    setting_type      TEXT
);

CREATE INDEX IF NOT EXISTS ix_stone_line ON line_stone(order_line_id, position);

-- ---------------------------------------------------------------- delivery

CREATE TABLE IF NOT EXISTS delivery (
    id           TEXT PRIMARY KEY,
    number       INTEGER NOT NULL UNIQUE,
    order_id     TEXT NOT NULL REFERENCES sales_order(id) ON DELETE RESTRICT,
    delivered_on TEXT NOT NULL,
    received_by  TEXT,
    notes        TEXT,
    created_at   TEXT NOT NULL
);

CREATE INDEX IF NOT EXISTS ix_delivery_order ON delivery(order_id);
CREATE INDEX IF NOT EXISTS ix_delivery_date  ON delivery(delivered_on);

CREATE TABLE IF NOT EXISTS delivery_line (
    delivery_id   TEXT NOT NULL REFERENCES delivery(id) ON DELETE CASCADE,
    order_line_id TEXT NOT NULL REFERENCES order_line(id) ON DELETE RESTRICT,
    quantity      INTEGER NOT NULL CHECK (quantity > 0),
    PRIMARY KEY (delivery_id, order_line_id)
);

-- ---------------------------------------------------------------- payment

CREATE TABLE IF NOT EXISTS payment (
    id            TEXT PRIMARY KEY,
    number        INTEGER NOT NULL UNIQUE,
    order_id      TEXT NOT NULL REFERENCES sales_order(id) ON DELETE RESTRICT,
    order_line_id TEXT REFERENCES order_line(id) ON DELETE SET NULL,
    amount_paise  INTEGER NOT NULL CHECK (amount_paise > 0),
    paid_on       TEXT NOT NULL,
    method        TEXT,
    reference     TEXT,
    is_refund     INTEGER NOT NULL DEFAULT 0,
    created_at    TEXT NOT NULL
);

CREATE INDEX IF NOT EXISTS ix_payment_order ON payment(order_id);
CREATE INDEX IF NOT EXISTS ix_payment_date  ON payment(paid_on);

-- ---------------------------------------------------------------- platform

CREATE TABLE IF NOT EXISTS number_sequence (
    name       TEXT PRIMARY KEY,
    next_value INTEGER NOT NULL
);

INSERT INTO number_sequence (name, next_value) VALUES
    ('order',    1000),
    ('delivery',  100),
    ('payment',  5000)
ON CONFLICT(name) DO NOTHING;

CREATE TABLE IF NOT EXISTS audit_log (
    id        TEXT PRIMARY KEY,
    actor     TEXT,
    action    TEXT NOT NULL,
    entity    TEXT NOT NULL,
    entity_id TEXT,
    at        TEXT NOT NULL,
    payload   TEXT
);

CREATE INDEX IF NOT EXISTS ix_audit_entity ON audit_log(entity, entity_id);
CREATE INDEX IF NOT EXISTS ix_audit_at     ON audit_log(at);
